async function api(path,body=null,params={}){const q=new URLSearchParams();for(const[k,v]of Object.entries(params))if(v!==null&&v!==undefined&&v!=='')q.set(k,v);const response=await fetch(new URL(`${path}${q.size?'?'+q:''}`,API_BASE),{cache:'no-store',...(body===null?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})});let value;try{value=await response.json();}catch{throw new Error('本机服务仍是旧版本，请关闭旧启动窗口并重新双击“启动星图.cmd”。');}if(!response.ok)throw Object.assign(new Error(value.message??'本机读取失败'),{code:value.error});return value;}
function showError(error){toast(error.message??String(error));}
