  sceneTip('brain-only',scene.brainOnly?'显示女孩模型':'隐藏女孩模型，只看星图',!!scene.brainOnly);
  sceneTip('drag-mode',scene.dragMode==='pan'?'拖动模式：平移，点击切换旋转':'拖动模式：旋转，点击切换平移',scene.dragMode==='rotate');
