function setInputPanel(open){panelLayout.bottom=open;$('input-dock').hidden=!open;document.querySelector('.stage').classList.toggle('input-collapsed',!open);syncPanelButton('toggle-input-dock',open,'底部输入面板',open?'收起输入 ⌄':'展开输入 ⌃');scene.viewChanged();}
