function regionName(id){if(id?.startsWith('L:'))return id==='L:forgotten'?'遗忘终点':layerName(id.slice(2));return s.overview?.regions.find(r=>r.id===id)?.name??({IN:'感知入口',OUT:'表达出口',display:'呈现密度'})[id]??id;}
function layerName(id){if(id==='forgotten')return '遗忘终点';return s.overview?.layers.find(l=>l.id===id)?.name??id;}
async function appendCentralRules(region,target,request){
  const data=await api('central-rules',null,{scope:s.scope,region});if(request!==panelGeneration)return;
  target.append(el('h3','',`中枢规则 · ${data.items.length} 条`),el('p','hint','有来源的内隐准则在条件匹配时作用于本中枢，可查看、暂停和撤回。'));
  for(const item of data.items){const row=btn('','memory-row',()=>openMemory(item.id,item.scope));row.append(el('strong','',item.label),el('small','',`${item.effective?'生效':'未生效'} · ${item.rule.condition} · ${item.reason}`));target.append(row);}
  if(!data.items.length)target.append(el('p','hint','尚无已确认的规则。打开重要记忆，通过“行为准则”提炼图式，再核对接入。'));
  if(data.candidates.length){target.append(el('h3','','可核对的图式'));for(const item of data.candidates.slice(0,6))target.append(btn(item.label,'memory-row',()=>openMemory(item.id,item.scope)));}
}
