async function refresh({initial=false}={}){const g=++generation;try{const [overview,config]=await Promise.all([api('overview'),api('config')]);s.config=config;if(g!==generation)return;s.overview=overview;updateModelStatus();if(initial)s.cursor=overview.stats.events;const select=$('scope'),old=s.scope;select.replaceChildren();const all=el('option','','本机总览');all.value='all';select.append(all);for(const scope of overview.scopes){const n=el('option','',`${scope.label} · ${number(scope.count)}`);n.value=scope.id;select.append(n);}s.scope=old==='all'||overview.scopes.some(x=>x.id===old)?old:'all';select.value=s.scope;
    $('source-count').textContent=number(overview.stats.sources);$('object-count').textContent=number(overview.stats.objects);const statuses={watching:'Aurabot 实时只读',reading:'正在只读同步',partial_read:'部分来源待重试',read_failed:'读取失败 · 副本仍在',source_unavailable:'上游暂不可用',stopped:'导入副本模式',host_connected:'Aurabot 模块已接入'};$('live-status').textContent=statuses[overview.live.status]??overview.live.status;$('live-light').classList.toggle('connected',['watching','host_connected'].includes(overview.live.status));
    renderSidebar();await loadGraph(g);if(initial)loadRecentHistory(g).catch(showError);$('error-state').hidden=true;$('sea-canvas').dataset.snapshotState='current';s.snapshotStale=false;if(initial&&panelGeneration===0)welcome();updateTarget();return true;
  }catch(error){
    const cached=!!s.graph;$('sea-canvas').dataset.snapshotState='stale';$('error-state').hidden=cached;
    if(cached){if(!s.snapshotStale)toast('星图暂时无法更新，继续显示上次快照；恢复连接后自动更新。');s.snapshotStale=true;}
    else{$('error-state').querySelector('h2').textContent='暂时无法读取星图';$('error-message').textContent='请稍后点击重新连接。'+(s.overview?.integration?.mode==='aurabot-module'?'若持续失败，请检查 DSH 中本模块的运行状态。':'请确认星图本机服务仍在运行。');}
    return cached;
  }}
async function loadRecentHistory(g){const after=Math.max(0,s.cursor-80),history=await api('events',null,{after,scope:'all',limit:80});if(g!==generation)return;s.events=uniqueEvents([...history.events,...s.events].sort((a,b)=>a.sequence-b.sequence));if(s.events.length){s.lastRun=s.replayEvents?s.lastRun:s.events.at(-1).run_id;s.cursor=Math.max(s.cursor,s.events.at(-1).sequence);}}
async function loadGraph(g=generation){const request=++graphRequest,scope=s.scope,layer=s.layer;const graph=await api('graph',null,{scope,layer,focus_id:s.selected?.id});if(g!==generation||request!==graphRequest||scope!==s.scope||layer!==s.layer)return false;graph.display=s.config?.effective_config.display;graph.recent_hours=s.config?.effective_config.W5.recent_hours;s.graph=graph;scene.setGraph(graph);$('scene-status').textContent=`底座显示 ${number(graph.counts.visible)} / ${number(graph.counts.matching)} 个对象 · ${s.overview.stats.pending?number(s.overview.stats.pending)+' 项待交接':'重要原文保持完整'} · 归档 L0 ${graph.archive?.l0??0} / L1 ${graph.archive?.l1??0} / L2 ${graph.archive?.l2??0}`;if(s.panel==='list')renderList({reveal:false});return true;}
