function welcome({reveal=false}={}){++panelGeneration;setMainView('overview');scene.domainFocus=null;s.panel='welcome';s.selected=null;const p=panel({reveal});title(p,'V5 / 工作、组织、底座','记忆不止于输入。','工作区、记忆目录与底座的可视投影全部位于头部。具体内容仍由统一底座保存。');p.append(el('div','notice','丘脑核群接收完整原话，前额皮层立即可读；海马体随后完成经历归组、来源对齐、目录更新与保护交接。四个组织区只保存摘要和引用。七个留存区域在脑内可见：近事进入巩固后分流，重要证据保留、图式可形成中枢准则；普通残迹逐步退出活跃层，原文默认无损归档。真正抹除时才以流星表示消失。L0 原话、L1 日摘要、L2 月印象共用同一底座。'));p.append(el('h3','','沿一段真实记忆查看'));p.append(btn('打开底座列表','quiet full',()=>{s.panel='list';renderList();}));p.append(el('h3','','观察一次流程'));p.append(el('p','hint','在下方切换“输入记忆”，写入本地验证台；随后用线索检索。真实操作会在中枢的专属出入口之间流动，完整轨迹保存在右上标签中。'));p.append(el('div','notice','基本交接由本地规则保障；DeepSeek 用于选定内容的语义候选与面板表达。入请求、模型标注引用与真实反馈分别记录，不向 Aurabot 发送。'));p.append(btn('查看功能与实现边界','text-button',showAbout));}
