function renderList({reveal=true}={}){++panelGeneration;setMainView('overview');scene.domainFocus=null;s.panel='list';const p=panel({reveal});title(p,'U / 规范内容','底座记忆列表',s.layer?`${layerName(s.layer)}：${s.overview.layers.find(l=>l.id===s.layer)?.description}`:'每个规范对象只保存一份。目录中的入口不会增加记忆数量。');for(const m of(s.graph?.nodes??[]).slice(0,s.listLimit))p.append(memoryRow(m));if(!s.graph?.nodes.length)p.append(el('p','hint',s.layer==='implicit'?'当前还没有满足条件的内隐准则。反馈与学习栏目可查看自动成熟门槛；也可从来源手动提炼并核对接入。':'当前范围或层级没有可显示对象。'));if(s.graph?.nodes.length>s.listLimit)p.append(btn('再展开 20 个对象','quiet load-more',()=>{s.listLimit+=20;renderList();}));p.append(el('div','notice',`当前可见 ${s.graph?.counts.visible??0} 个，匹配 ${s.graph?.counts.matching??0} 个。显示限额不删除底座内容；可按范围、层级或检索线索定位。`));}
