async function openRegion(id){const request=++panelGeneration,r=s.overview.regions.find(r=>r.id===id);if(!r)return;s.region=id;s.selected=null;s.panel='region';setMainView(id.startsWith('M')?'directory':'overview');scene.domainFocus=id.startsWith('M')?'memory':null;scene.selected=id;renderSidebar();const p=panel();title(p,`${id} / ${r.domain==='memory'?'组织入口':'工作中枢'}`,r.name,r.function);if(r.anatomy)p.append(el('p','panel-meta',r.anatomy+' 艺术布局不等同真实脑仿真。'));if(r.mist_shape)p.append(el('p','panel-meta','薄雾形状：'+r.mist_shape+'；形状为解剖启发的体积示意。'));if(r.research){const link=el('a','text-button','查看命名与位置依据 ↗');link.href=r.research;link.target='_blank';link.rel='noopener noreferrer';p.append(link);}const actions=el('div','panel-actions');actions.append(btn('聚焦此处','',()=>scene.focusRegion(id)),btn('对应参数','',()=>renderParameters(id)));p.append(actions);
  const linked=s.overview.channels.filter(c=>[c.from,c.to].includes(id));p.append(el('h3','',`专属出入口 · ${linked.length} 条连接`));for(const c of linked)p.append(el('p','progress-row',`${r.name} ⇄ ${regionName(c.from===id?c.to:c.from)} · 独立端口`));
  if(r.domain==='memory'){const result=await api('directory',null,{scope:s.scope,region:id,limit:40});if(request!==panelGeneration)return;p.append(el('h3','',`${number(result.total)} 个目录 · 正文在 U`));for(const entry of result.entries){const row=btn('','catalog-row',()=>openCatalog(entry));row.append(el('strong','',entry.label),el('small','',`${entry.ref_count} 个规范引用 · ${entry.summary}`));p.append(row);}if(!result.entries.length)p.append(el('p','hint','当前范围还没有该类目录。'));}
  if(r.domain==='work')await appendCentralRules(id,p,request);
  if(id==='U'){p.append(btn('三层归档与完整原话','quiet full',()=>inspectorTools.archive()),btn('上下文洞察','text-button',()=>inspectorTools.context()),btn('展开分层内容','quiet full',renderList),btn('呈现密度与显示预算','text-button',()=>renderParameters('display')));}}
async function openCatalog(entry){++panelGeneration;const p=panel();s.panel='catalog';title(p,'目录命中 → 统一底座',entry.label,entry.summary);p.append(el('div','notice','这里只是目录。点击以下入口会从 U 读取规范对象及其原话，不把组织摘要当作具体经历。'));if(entry.topics?.length){p.append(el('h3','','来源明确的话题链'));for(const t of entry.topics)p.append(el('p','hint',`${t.topic} · ${t.refs.length} 个引用`));}p.append(btn('沿此目录查找底座记忆','quiet full',()=>runQuery('',entry.region,entry.id)));p.append(el('h3','','目录中的规范引用'));for(const id of entry.refs){const m=s.graph.nodes.find(n=>n.id===id);p.append(btn(m?.label??'打开规范对象','memory-row',()=>openMemory(id,entry.scope)));}}
function parameterRow(region,key,definition,values,explanation){
  const [label,min,max,step]=definition,row=el('div','param-row'),head=el('div','param-head'),name=el('span','param-name');
  const input=el('input'),caption=el('label','',label),out=el('output','',String(values[key]));
  input.id=`param-${region}-${key}`;caption.htmlFor=input.id;out.setAttribute('for',input.id);
  const switchParam=key==='group_policy_enabled';
  input.type=switchParam?'checkbox':key.startsWith('group_')?'number':'range';input.min=min;input.max=max;input.step=step;input.value=values[key];
  if(switchParam){input.checked=values[key]===1;input.setAttribute('role','switch');}
  input.setAttribute('aria-label',`${regionName(region)} ${label}`);
  input.addEventListener('input',()=>{values[key]=switchParam?Number(input.checked):Number(input.value);out.textContent=String(values[key]);});
  const body=el('div','param-help');body.id=input.id+'-help';body.hidden=true;
  if(explanation){
    const list=el('dl','param-help-list');
    for(const [field,title] of [['meaning','含义'],['effect','作用'],['higher','调高后'],['lower','调低后']])list.append(el('dt','',title),el('dd','',explanation[field]));
    body.append(list);if(explanation.note)body.append(el('p','param-help-note',explanation.note));
  }else body.append(el('p','param-help-note','参数说明尚未载入，请关闭旧启动窗口，重新运行“启动星图.cmd”后打开此参数面板。'));
  body.append(el('p','param-help-range',`范围 ${min}～${max} · 步长 ${step} · 调节后点击“保存并生效”`));
  const toggle=btn('','param-help-toggle',()=>{
    const expanded=body.hidden;body.hidden=!expanded;toggle.setAttribute('aria-expanded',String(expanded));
    toggle.setAttribute('aria-label',`${expanded?'收起':'展开'}“${label}”的参数说明`);
    toggle.title=expanded?'收起参数说明':'展开参数说明';
    if(expanded)input.setAttribute('aria-describedby',body.id);else input.removeAttribute('aria-describedby');
  });
  toggle.setAttribute('aria-controls',body.id);toggle.setAttribute('aria-expanded','false');
  toggle.setAttribute('aria-label',`展开“${label}”的参数说明`);toggle.title='展开参数说明';
  const arrow=el('span','param-help-chevron','⌄');arrow.setAttribute('aria-hidden','true');toggle.append(arrow);
  name.append(caption,toggle);head.append(name,out);row.append(head,input,body);return row;
}
async function renderParameters(id){
  if(window.parent!==window&&s.overview?.integration?.mode==='aurabot-module'){
    const p=panel();s.panel='params';title(p,'',regionName(id)+' · 参数','完整参数位于 Thinkstar 对应星区的可收起栏目。');
    p.append(btn('打开对应参数栏目','quiet full',()=>window.parent.postMessage({type:'thinkstar-open-settings',region_id:id},window.location.origin)));return;
  }
  const request=++panelGeneration,p=panel();s.panel='params-loading';title(p,'参数','正在读取参数…');const config=await api('config');if(request!==panelGeneration)return;
  s.config=config;s.panel='params';
  title(p,`${id} / 生效配置 v${config.version}`,regionName(id)+' · 参数','调整保存在 Thinkstar，所有事实、来源、范围和保护硬约束保持独立。');
  const definitions=config.params[id];if(!definitions)return;
  p.append(el('p','param-instructions','点击参数名称旁的向下按钮，查看含义、作用和调高／调低的影响。各项可独立展开。'));
  const values={...config.effective_config[id]};
  const groupKeys=id==='W5'?config.group_policy_keys??[]:[];
  for(const [key,definition] of Object.entries(definitions))if(!groupKeys.includes(key))p.append(parameterRow(id,key,definition,values,config.param_help?.[id]?.[key]));
  if(groupKeys.length){
    const group=el('details'),status=el('p','hint');
    group.append(el('summary','','群聊专用压缩与遗忘'),el('p','hint','仅普通群聊。私聊沿用原策略，重要内容与未完事项继续保护。按原消息起算，每天为连续 24 小时，日期显示北京时间。到期即停止自动召回，夜间移入 rubbishmemory；移入后请从垃圾桶查看或恢复。关闭策略不会自动恢复已移入的内容。'),status);
    const coverage=el('p','hint','正在检查原生注入适配…');group.append(coverage);
    for(const key of groupKeys)group.append(parameterRow(id,key,definitions[key],values,config.param_help?.[id]?.[key]));
    group.append(btn('打开治理预览','text-button',showGovernance));p.append(group);
    let loaded=false;
    group.addEventListener('toggle',async()=>{
      if(!group.open||loaded)return;
      try{const g=await api('group-lifecycle',null,{scope:s.scope});if(request!==panelGeneration)return;
        coverage.textContent=Object.values(g.coverage??{}).filter(value=>value==='covered_with_conservative_holds').length===2?'原生 memory 与 history-vault 已接入；无法对齐的旧画像／摘要暂时保留。':'原生注入尚未全部接通，请检查配套适配状态。';
        status.textContent=(g.enabled?'群聊专用期限已启用':'继承原有策略')+' · v'+g.version+(g.enabled?' · 对象数：待整理 '+g.pending+' · 已整理 '+g.processed+' · 受保护 '+g.protected+' · 无法判断 '+g.unknown+' · 已到期待转移 '+g.expired+' · 废弃库 '+g.retired:'');
        for(const [reason,count] of Object.entries(g.blocked??{}))group.append(el('p','hint',(g.blocked_labels?.[reason]??reason)+'：'+count));loaded=true;
      }catch(error){status.textContent=error.message;}
    });
  }
  const actions=el('div','config-actions');actions.append(btn('保存并生效','quiet',async()=>{s.config=await api('config',{region:id,values,expected_version:config.version});toast('参数已保存，下一次对应操作使用新配置');renderParameters(id);}));p.append(actions);
  if(config.history.length){
    const rollback=el('select','panel-input');rollback.setAttribute('aria-label','选择参数回退版本');
    for(const h of config.history.slice().reverse()){const o=el('option','',`v${h.version} · ${date(h.at)}`);o.value=h.version;rollback.append(o);}
    p.append(rollback,btn('回退到此版本','text-button',async()=>{await api('rollback-config',{version:Number(rollback.value),expected_version:config.version});toast('配置已回退并生成新版本');renderParameters(id);}));
  }
  p.append(el('div','notice',config.hard_rules.join('；')));
}

