async function replay(id){const request=++panelGeneration;renderRuns();const trace=await api('trace',null,{id});if(request!==panelGeneration||s.panel!=='runs')return;scene.setAtlas(true);scene.domainFocus=null;scene.pulses=[];$('flow-state').textContent='正在回放已保存的轨迹，不会重新执行';trace.events.forEach((e,i)=>scene.event(e,{replay:true,index:i}));s.events=uniqueEvents([...s.events,...trace.events]);s.lastRun=id;s.replayEvents=trace.events;renderRuns();}
function uniqueEvents(items){return [...new Map(items.map(x=>[x.id,x])).values()].slice(-300);}
