async function showGovernance(){const request=++panelGeneration,p=panel();s.panel='governance';s.selected=null;setMainView('governance');scene.domainFocus='work';scene.selected='W5';scene.focusRegion('W5');title(p,'W5 / 治理','巩固与容量治理','正在读取治理资料…');const g=await api('governance');if(request!==panelGeneration||s.panel!=='governance')return;title(p,'W5 / 保护优先，先看再处理','巩固与容量治理','所有写入只发生在 Thinkstar 独立运行库。');const grid=el('div','stats-grid');for(const[v,label]of [[g.protected,'保护对象'],[g.stats.pending,'待交接'],[g.stats.failed,'失败待检查'],[(g.stats.bytes/1048576).toFixed(1),'底座 MB']]){const c=el('div');c.append(el('b','',v),el('span','',label));grid.append(c);}p.append(grid,el('div','notice',`保护检查异常 ${g.health.length} 项；后台最老积压 ${date(g.stats.oldest_pending)}。容量预算 ${g.capacity_mb} MB。`));const bar=el('div','capacity-bar'),fill=el('i');fill.style.width=Math.min(100,g.capacity_used_ratio*100)+'%';bar.append(fill);p.append(bar,btn('预览当前范围的分层与遗忘计划','quiet full',async()=>{const plan=await api('retention-plan',{scope:s.scope});renderPlan(plan,p);}));p.append(el('h3','','硬约束'));for(const rule of g.hard_rules)p.append(el('p','hint','• '+rule));p.append(btn('打开记忆垃圾桶','quiet full',()=>showTrash()));p.append(btn('海马体治理参数','text-button',()=>renderParameters('W5')));for(const job of g.jobs)p.append(el('p','progress-row',`${job.status} · 尝试 ${job.attempts} · ${job.error??'等待短批次处理'}`));}
function renderPlan(plan,p){const box=el('div');box.append(el('h3','',`本次计划 ${plan.items.length} 项 · 阻止 ${plan.blocked.length} 项`));const names={move:'层级迁移',pack:'无损冷存',summarize:'有损要旨',group_archive:'群聊原文无损冷存／本地残迹',group_trash:'群聊到期移入废弃库',forget:'移入记忆垃圾桶'};for(const item of plan.items.slice(0,30))box.append(el('p','progress-row',`${names[item.action]} → ${layerName(item.target)} · ${item.reason}`));if(!plan.items.length)box.append(el('p','hint','当前没有符合处理条件的内容。近期、保护和未完事项不会为了展示动画被遗忘。'));else{if(plan.items.every(item=>item.action==='group_archive'))box.append(el('p','hint','本批整理无损冷存原文并缓存本地要旨。默认召回资格按消息期限实时判定。'));else box.append(el('div','notice warning','执行会改变 Thinkstar 的存储精度；遗忘会先保存可恢复副本，再退出活跃层；关闭原文归档时显示退役流星。Aurabot 和原始导入档案保持不变，已遗忘 ID 不会被实时同步复活。'));box.append(btn('执行这份已预览的计划','quiet full',async()=>{const result=await api('retention-apply',{plan_id:plan.id});s.lastRun=result.run_id;await consumeTrace(result.run_id);await refresh();toast(`治理已执行：${result.items.length} 项`);showGovernance();}));}p.append(box);}
async function showAbout(){const p=$('about-content');p.replaceChildren(el('p','','设计基准：thinkstar-memory-design-v5.md。五个工作中枢、四个记忆组织入口、一份统一分层底座。角色已导入用户提供的 GLB，保留原始网格、法线及星点发光贴图，星图模式保留轮廓柔光、反射高光和彩色星点，衣裙与尾巴保留更多形体，头部中央更通透；近看仍保留玻璃边缘。模型原貌可单独观察；默认聚焦头部，滚轮推进可进入脑内，星图与模型共用相机和近裁剪面；脑区位置采用功能研究启发的布局。'),el('p','','Aurabot 只通过白名单文件实时读取，SQLite 只打开 Thinkstar 的副本。这里的输入、反馈、参数、记忆修订和治理只写入 runtime-data/v5。没有向 Aurabot 发送或写入的接口。'),el('p','','已接入：L0完整归档／L1日摘要／L2月印象、BM25排序、可撤回事实键、上下文账本、原文即时保存、显式规则归组、保护交接、四区目录、词法／实体检索、来源去重、有限联想、参数版本、反馈修订、分层治理和真实运行回放。'),el('p','','模型接口已支持 DeepSeek / deepseek-flash，通过本机环境变量配置密钥。语义候选必须保留来源并待核对，模型标注的引用不冒充内部使用证据。向量索引、多模态采集和外部主动发送仍未接入。原上游缺失的来源、线程和历史对象版本不会被补造。'));if(s.overview?.integration?.mode==='aurabot-module'){p.children[1].textContent='当前作为 Aurabot 用户模块运行：通过 message、activity、send、chat/log 观察接收资料，并同步内置记忆公开接口的成功记录，只写 modules-data/thinkstar-memory。prompt 返回当前人格、当前聊天的记忆背景，主对话和发送仍由宿主完成。模块启停同时回收钩子、路由和数据库；不修改内置记忆、源码或总配置。';p.children[3].textContent='可选语义整理与星图对话通过 DSH api.ask 调用当前模型，由宿主管理凭据。正常聊天通过 DSH 会话计量估算空间，并观察模型请求边界、完成状态与整次调用的真实用量；实际采用不由请求成功推断。星图 api.ask 调用仍不返回准确用量。宿主日志中的机器人回复缺少人格标识，保存到人格未归属的观察范围，不自动注入当前人格。';}$('about-dialog').showModal();}
async function poll(){if(polling||!s.overview||!scene.running||!atlasForeground())return;polling=true;try{const value=await api('events',null,{after:s.cursor,scope:'all',limit:200});if(value.events.length){let i=0;for(const e of value.events){s.cursor=Math.max(s.cursor,e.sequence);if(s.events.some(x=>x.id===e.id))continue;s.events.push(e);if(s.scope==='all'||e.scope===s.scope)scene.event(e,{index:i++});if(e.meteor&&s.selected?.id===e.memory_id)openMemory(s.selected.id,s.selected.scope).catch(showError);if(!s.replayEvents&&(s.scope==='all'||e.scope===s.scope))s.lastRun=e.run_id;}$('flow-state').textContent=`最近操作：${value.events.at(-1).operation}`;s.events=s.events.slice(-300);if(s.tab==='runs'&&!s.replayEvents)renderRuns({reveal:false});if(s.panel==='memory'&&s.selected)refreshHandoff().catch(()=>{});clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>refresh(),700);}}catch{}finally{polling=false;}}
$('scope').addEventListener('change',async()=>{const request=++panelGeneration,previousView=s.mainView,previousPanel=s.panel;s.panel='loading';s.scope=$('scope').value;s.replayEvents=null;s.layer=null;s.selected=null;s.listLimit=20;s.graph=null;scene.nodes.clear();title(panel(),'范围已切换','正在读取该范围…');updateTarget();if(!await loadGraph()||request!==panelGeneration)return;renderSidebar();if(previousPanel==='archive')await inspectorTools.archive();else if(previousPanel==='context')await inspectorTools.context();else if(previousPanel==='recalls')await renderRecalls();else if(previousView==='directory')await showDirectory();else if(previousView==='replay')await openReplay({play:false});else if(previousView==='governance')await showGovernance();else renderList();});$('submit-entry').addEventListener('click',()=>submit().catch(showError));$('entry-text').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();submit().catch(showError);}});
