$('tab-inspect').addEventListener('click',()=>{if(s.tab==='inspect')return;if(s.selected)openMemory(s.selected.id,s.selected.scope).catch(showError);else if(s.region)openRegion(s.region).catch(showError);else welcome();});$('tab-runs').addEventListener('click',()=>openReplay({play:false}).catch(showError));for(const id of['tab-recalls','recent-recalls'])$(id).addEventListener('click',()=>renderRecalls().catch(showError));$('view-overview').addEventListener('click',()=>{scene.focusRegion('HEAD');scene.selected=null;welcome();});$('view-directory').addEventListener('click',()=>showDirectory().catch(showError));$('view-replay').addEventListener('click',()=>openReplay().catch(showError));$('view-governance').addEventListener('click',()=>showGovernance().catch(showError));$('about-button').addEventListener('click',showAbout);$('close-about').addEventListener('click',()=>$('about-dialog').close());$('retry-button').addEventListener('click',()=>playback.update(atlasForeground(),{retry:true}));
async function refreshHandoff(){const selected=s.selected;if(!selected)return;const data=await api('detail',null,{id:selected.id,scope:selected.scope});if(s.panel!=='memory'||s.selected?.id!==selected.id)return;const box=$('handoff-progress');if(box){const index=data.handoff_states.indexOf(data.memory.handoff);box.replaceChildren(...data.handoff_states.map((key,i)=>el('div',`progress-row ${i<=index?'done':''}`,`${i<=index?'✓':'○'} ${handoff[key]}`)));}}
function updateModelStatus(){const model=s.overview?.model,host=model?.provider==='DSH',name=host?'DSH 模型':'DeepSeek';$('model-button').textContent=name+(model?.verified?' · 已连接':model?.configured?(host?' · 已允许':' · 已配置'):' · 未启用');if(!model?.configured)$('use-model').checked=false;const label=$('use-model').parentElement;for(const node of label.childNodes)if(node.nodeType===Node.TEXT_NODE)node.textContent=name;}

async function showModelPanel(){const request=++panelGeneration,p=panel();setMainView(null);s.panel='model';title(p,'MODEL','模型配置','正在读取…');const status=await api('model-status',null,{refresh:1});if(request!==panelGeneration||s.panel!=='model')return;title(p,'MODEL / 指定的模型服务',(status.provider==='DSH'?'DSH · ':'DeepSeek · ')+(status.model??'尚未配置'),status.base_url??'当前模型未启用');p.append(el('div','notice',status.provider==='DSH'?`使用 DSH 管理的当前模型；额外面板调用：${status.configured?'已允许':'未允许'}。用量由宿主掌握，Thinkstar 不读取密钥。`:`本机密钥：${status.configured?'已配置':'未检测到'}；最近调用：${status.verified?'成功':'尚未验证'}。密钥不进入网页或项目文件。`));p.append(el('p','hint','语义整理只发送当前选定对象的来源。模型对话限定在选定空间，携带必要近期上下文；不会把整个记忆库上传，也不会向 Aurabot 输出。'));const checkConnection=btn('检查模型连接','quiet full',async()=>{const result=await api('model-check',{});toast(result.usage.known===false?'DSH 模型已连接；宿主未提供本次 token 用量':`DeepSeek 已连接，本次测试 ${result.usage.total_tokens} tokens`);await refresh();showModelPanel();});checkConnection.disabled=!status.configured;checkConnection.title=status.configured?'检查已配置的模型连接':'先启用模型服务后再检查连接';p.append(checkConnection);p.append(btn(status.provider==='DSH'?'启用 DSH 模型面板回答':'启用 DeepSeek 面板回答','quiet full',()=>{if(!status.configured){toast(status.provider==='DSH'?'先在模块设置中允许调用 DSH 模型':'先双击项目中的“配置模型密钥.cmd”');return;}$('use-model').checked=true;toast('已启用。选择对应范围，再在下方输入要说的话。');}));p.append(btn('使用本地检索表达','text-button',()=>{$('use-model').checked=false;toast('已切回本地原文检索');}));p.append(el('div','notice','模型提取先成为有逐字证据的候选。证据不匹配、数字改变、输出截断或版本过期时不提交。模型自报引用与可核验的真实使用不同；沉默仍为未知反馈。'));}
async function extractMemory(memory){if(!s.overview?.model?.configured){await showModelPanel();return;}toast('正在处理当前选定记忆；原文保持可读，分块会保存检查点。');const result=await api('semantic-extract',{scope:memory.scope,id:memory.id,chunk_limit:2});s.lastRun=result.run_id;await consumeTrace(result.run_id);toast(result.status==='complete'?`语义候选已对齐来源：${result.created_ids?.length??0} 个；请核对后确认`:`已完成 ${result.completed_chunks??0}/${result.total_chunks??0} 块，再点“语义整理”继续`);await refresh();if(s.selected?.id===memory.id)await openMemory(memory.id,memory.scope);}
