window.addEventListener('message',event=>{
  if(window.parent===window||event.source!==window.parent||event.origin!==window.location.origin)return;
  if(event.data?.type==='thinkstar-config-updated'){s.config=null;refresh().catch(showError);return;}
  if(event.data?.type!=='thinkstar-atlas-focus')return;
  Promise.resolve().then(async()=>{
    if(!s.overview)await refresh();
    const {region_id,memory_id,scope}=event.data;
    if(memory_id&&scope){s.scope=scope;s.layer=null;s.selected={id:memory_id,scope};await loadGraph();await openMemory(memory_id,scope);scene.focusMemory(memory_id);}
    else if(typeof region_id==='string'){scene.selected=region_id;scene.focusRegion(region_id);if(region_id.startsWith('L:'))await setLayer(region_id.slice(2));else await openRegion(region_id);}
  }).catch(showError);
});
